const D=window.GMCH,app=document.getElementById('app'),sources=new Map(D.sources.map(s=>[s.source_id,s]));let note='',consent=false;const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');let state;const t=(z,e)=>state.lang==='zh-Hans'?z:e;const local=x=>x?.[state.lang]||x?.en||x||'';const countries=[['MYS','马来西亚','Malaysia'],['USA','美国','United States'],['CHN','中国','China'],['JPN','日本','Japan'],['EA','欧元区','Euro area'],['GBR','英国','United Kingdom'],['GLOBAL','世界','World']];function read(){const u=new URL(location.href);state={lang:u.searchParams.get('lang')==='en'?'en':'zh-Hans',id:u.searchParams.get('id')||'',country:u.searchParams.get('country')||'MYS',period:u.searchParams.get('period')||'2024',scale:u.searchParams.get('scale')||'now',q:u.searchParams.get('q')||''};}function go(x,push=true){if(x.country||x.period){consent=false;note='';}const u=new URL(location.href);for(const[k,v]of Object.entries({...state,...x}))v?u.searchParams.set(k,v):u.searchParams.delete(k);history[push?'pushState':'replaceState']({},'',u);read();render();}function source(id){const s=sources.get(id);if(!s)return '';const href=s.localeHrefs?.[state.lang]||s.official_url;return `<div class="source-row"><a href="${esc(href)}" target="_blank" rel="noopener">${esc(publisher(s.publisher))} · ${esc(s.label?local(s.label):t('官方来源','Official source'))} ↗</a><p class="minor">${esc(t('适用范围与元数据见来源登记；不等于当前事实已核实。','See the source registry for scope and metadata; a link is not a verified current fact.'))}</p>${s.locales?`<details><summary>${t('已发布原文与位置','Published passages and locators')}</summary>${s.locales[state.lang].passages.map(p=>`<p>${esc(p.text)}</p><small>${esc(p.pointer)} · ${esc(p.anchor)}</small>`).join('')}</details>`:''}</div>`;}function controls(){return `<div class="scope"><label>${t('地区','Place')}<select data-country>${countries.map(([id,z,e])=>`<option value="${id}" ${state.country===id?'selected':''}>${t(z,e)}</option>`).join('')}</select></label><label>${t('观察年份','Observation year')}<select data-period>${['2022','2024','2025','2026'].map(v=>`<option ${state.period===v?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="scale-switch" role="group" aria-label="${t('阅读尺度','Reading scale')}">${[['now','世界现况','World now'],['history','结构与历史','Structure & history'],['compare','比较与变化','Compare & change']].map(([id,z,e])=>`<button data-scale="${id}" aria-pressed="${state.scale===id}">${t(z,e)}</button>`).join('')}</div>`;}function link(q){return `<a href="?id=${q.id}&lang=${state.lang}&country=${q.country==='GLOBAL'?'MYS':q.country}&period=${q.period}" data-question="${q.id}">${esc(local(q.title))} →</a>`;}function search(){return `<form data-search><label for="question">${t('你想理解什么现实问题？','What would you like to understand?')}</label><div class="search-line"><input id="question" name="q" maxlength="1000" value="${esc(state.q)}" placeholder="${t('利率、贷款、买房与生活','Rates, credit, homes and everyday life')}"><button type="submit">${t('提问','Ask')}</button></div><small>${t('离线审阅：支持已列问题的确定性解释；未知问题保留缺口，不运行模型。','Offline review: deterministic explanations for listed questions. Unknown questions retain gaps; no model runs.')}</small></form>`;}function home(){const groups=[['利率、贷款、买房与生活','Rates, credit, homes & life',['Q02','Q03','Q04','Q11']],['日常负担与收入','Costs & income',['Q01','Q14','Q15']],['银行标准与借款需求','Standards & demand',['Q05','Q06','Q10']],['地区与制度差异','Places & institutions',['Q07','Q08','Q09','Q16']],['住房、工作与变化','Housing, jobs & change',['Q12','Q13','Q17']],['世界与我及连续阅读','The world, me & continuity',['Q18','Q19','Q20']]];return `<main id="main" class="wrap"><header class="answer-head"><p class="eyebrow">WORLD · GATE 2C</p><h1>${t('从现实问题，理解世界变化','Understand world changes through real questions')}</h1><p>${t('先读有依据的回答，再核对地区、年份与尚缺证据。','Start with a supported answer, then inspect place, time and missing evidence.')}</p>${search()}</header><div class="question-groups">${groups.map(([z,e,ids])=>`<section class="question-group"><h2>${t(z,e)}</h2>${ids.map(id=>link(D.questions.find(q=>q.id===id))).join('')}</section>`).join('')}</div><p><a href="../gate2/WORLD-R3-PROTOTYPE.html?lang=${state.lang}">${t('保留的 Gate 2／2B 问题、R2 地图与个人同意设计','Retained Gate 2/2B questions, R2 map and personal-consent design')} ↗</a></p></main>`;}
function observations(q){const rows=D.observations.filter(o=>o.country===state.country&&o.observation_period.startsWith(state.period)&&o.value!==null);if(!rows.length)return `<p class="scope-note" data-empty-scope>${t('未采集这个地区／年份的合格数值。不会沿用先前地区数值；一般解释仍可阅读。','No eligible values collected for this place/year. Previous-place values are not reused; general explanations remain available.')}</p>`;const relevant=rows.filter(o=>q.id==='Q05'?o.source_id==='fed-table-corrected':q.id==='Q06'?o.source_id.startsWith('hmda-aggregate-'):q.id==='Q02'?o.country==='MYS':q.id==='Q11'?o.metric_id==='median_household_income':false);if(!relevant.length)return `<p class="scope-note">${t('这道题未调用所选范围的数值，避免用背景指标冒充答案。','This question does not use values for the selected scope; background numbers are not substituted as the answer.')}</p>`;const table=`<div class="table-scroll" tabindex="0" aria-label="${t('可横向滚动的原始观察','Horizontally scrollable observations')}"><table><caption>${t('真实离线观察；不是实时数据','Actual offline observations, not live data')}</caption><thead><tr><th>${t('指标','Measure')}</th><th>${t('国家／观察期','Country / period')}</th><th>${t('值与单位','Value & unit')}</th><th>${t('发布与质量','Publication & quality')}</th></tr></thead><tbody>${relevant.map(o=>`<tr data-observation data-country="${o.country}" data-period="${o.observation_period}"><td>${metric(o)}</td><td>${esc(countries.find(c=>c[0]===o.country)?.[state.lang==='en'?2:1]||o.country)} · ${esc(o.observation_period)}</td><td>${esc(Number(o.value).toLocaleString(state.lang==='en'?'en-US':'zh-CN',{maximumFractionDigits:4}))} ${unit(o.unit)}</td><td>${esc(o.publication_date||t('首发日期未保留','Initial release date not retained'))}<br><a href="${esc(sources.get(({cpi:'MY_CPI',median_household_income:'MY_INCOME',survey_standards:'US_SLOOS',survey_demand:'US_SLOOS',application_action_count:'US_HMDA',application_amount:'MY_CCRIS',approval_amount:'MY_CCRIS',disbursement_amount:'MY_CCRIS'})[o.metric_id])?.official_url)}" target="_blank" rel="noopener">${t('原始来源','Original source')} ↗</a><br>${t('取样：2026-10-20；历史修订版','Sampled: 2026-10-20; revised historical vintage')}</td></tr>`).join('')}</tbody></table></div>${q.id==='Q02'?`<p>${t('CPI与收入仅作家庭条件背景，不构成房贷成功率证据。','CPI and income are household background, not mortgage success-rate evidence.')}</p>`:''}`;return q.id==='Q02'?`<details><summary>${t('核对原始观察表（可横向滚动）','Inspect observation table (scroll horizontally)')}</summary>${table}</details>`:table;}
function metric(o){return ({cpi:t('居民消费价格指数','Consumer price index'),median_household_income:t('家庭月总收入中位数','Median monthly gross household income'),survey_standards:t('政府类购房贷款：标准收紧净比例','Government home-purchase loans: net tightening'),survey_demand:t('政府类购房贷款：需求增强净比例','Government home-purchase loans: net stronger demand'),application_amount:t('住宅用途：申请金额','Residential purpose: amount applied'),approval_amount:t('住宅用途：批准金额','Residential purpose: amount approved'),disbursement_amount:t('住宅用途：放款金额','Residential purpose: amount disbursed'),housing_price_index:t('住宅价格指数','House price index'),application_action_count:t('购房贷款行动记录：','Home-purchase action records: ')+({'1':t('贷款发放','Originated'),'2':t('批准未接受','Approved not accepted'),'3':t('拒绝','Denied')}[o.action_taken]||'')})[o.metric_id]||t('未支持指标','Unsupported measure');}function unit(u){return ({index_2010_100:t('指数（2010=100）','index (2010=100)'),MYR_per_month:t('令吉／月','MYR/month'),net_percent_banks_tightening:t('% 银行净收紧','% banks net tightening'),net_percent_banks_stronger_demand:t('% 银行净需求增强','% banks net stronger demand'),MYR:t('令吉','MYR'),records:t('条记录','records')})[u]||esc(u);}
function graph(){return `<div class="mechanism-nodes">${D.graph.nodes.slice(0,6).map((n,i)=>`<details><summary>${i+1}. ${esc(local(n.label))}</summary><p>${t('这是可能的传递关系，受合同、收入预期、资金、供给与时间影响；反向反馈也可能存在。','This possible relationship depends on contracts, income expectations, funding, supply and time. Reverse feedback can also occur.')}</p>${source('ECB_MECHANISM')}</details>`).join('')}</div><p class="minor">${t('顺序表示阅读路径，不证明每条因果或所有国家都有相同传导。','The sequence guides reading; it does not establish every causal link or uniform transmission across countries.')}</p>`;}
function comparison(){const lines=[['MYS','申请／批准金额','Application / approved amounts'],['USA','银行标准／需求问卷与年度行动','Bank surveys and annual reported actions'],['CHN','开发商收到按揭资金','Mortgage funds received by developers'],['JPN','隔夜市场利率与住房调查','Overnight market rate and housing surveys'],['EA','银行贷款标准与需求净比例','Net bank standards and demand'],['GBR','扣除取消后的批准笔数','Approvals net of cancellations']];return `<div class="table-scroll" tabindex="0"><table><caption>${t('同看定义，不排列获批率','Compare definitions; no approval-rate ranking')}</caption><thead><tr><th>${t('地区','Place')}</th><th>${t('可用本地指标','Local metric')}</th><th>${t('统一获批率','Harmonised approval rate')}</th></tr></thead><tbody>${lines.map(([id,z,e])=>`<tr><td>${esc(countries.find(x=>x[0]===id)?.[state.lang==='en'?2:1])}</td><td>${t(z,e)}</td><td>${t('不可比；缺同口径分母','Not comparable; aligned denominator absent')}</td></tr>`).join('')}</tbody></table></div>`;}
function answer(){const q=D.questions.find(x=>x.id===state.id);if(!q)return `<main id="main" class="wrap"><h1>${esc(state.q||t('尚未覆盖的问题','Question not yet covered'))}</h1><p>${t('证据不足：离线候选未检索到支持这个问题的段落或观察。没有自动套用其他答案，也没有调用模型。','Insufficient evidence: this offline candidate has not retrieved supporting passages or observations for this question. No different answer is substituted and no model is called.')}</p>${search()}<a href="?" data-home>${t('返回','Back')}</a></main>`;const mismatch=q.id==='Q05'&&(state.country!=='USA'||state.period!=='2024');const direct=mismatch?t('需求与标准是不同量，本选择缺对应调查数据。已撤下美国2024年第三季度数值，不能转用于这个范围。','Demand and standards are different measures. This selection lacks matching survey data; US2024Q3 values have been removed and cannot be transferred.'):local(q.answer);return `<main id="main" class="wrap"><a href="?" data-home>← ${t('回到问题','Back to questions')}</a><header class="answer-head"><p class="eyebrow">${t('离线来源支持的审阅答案','Offline source-supported review answer')}</p><h1>${esc(state.q||local(q.title))}</h1>${controls()}</header><section class="direct" id="direct"><h2>${t('直接回答','Short answer')}</h2><p class="answer-copy">${esc(direct)}</p><p class="minor">${esc(local(q.limits))}</p></section><div class="answer-layout"><article class="answer-main"><section id="evidence"><h2>${t('证据与数据','Evidence & data')}</h2><p>${t('公开来源已读取；本页是受控答案设计，不是自由输入问答能力验收。','Public sources were read. This is a curated answer design, not acceptance of free-input answering.')}</p>${observations(q)}${q.id==='Q02'?loanChart()+cpiChart():''}${q.id==='Q02'?`<p class="scope-note">${t('全国申请成功率：不可测量。缺少相同申请群组的可比申请与批准件数。','National applicant success probability: not measurable. Matched application-cohort counts are unavailable.')}</p>`:''}</section><section><h2>${t('为什么会这样','How the mechanism can work')}</h2>${graph()}</section><section><h2>${t('生活中意味着什么','What this means in daily life')}</h2><p>${t('核对自己的住房合同、必要开销、收入余量与可调整空间。公共指标不能代替个人贷款报价或获批决定。','Check your housing contract, necessary costs, income margin and room to adjust. Public indicators do not replace a personal loan offer or approval decision.')}</p></section><section><h2>${state.scale==='history'?t('结构与历史边界','Structure & historical boundaries'):t('地区与历史比较','Places & historical comparison')}</h2>${state.scale==='history'?`<p>${t('美国2007–2010、日本泡沫后与中国2025年开发活动是不同机制对照。日本全文与各地匹配时序仍有缺口，不能写成同一原因。','The US2007–2010 crisis, Japan’s post-bubble experience and China’s2025 development activity are different mechanism comparisons. Japan full-text and aligned local series remain incomplete; a single cause is not established.')}</p><a href="WORLD-R3-GMCH-CASE-BOUNDARIES.md">${t('查看历史来源及限制','Inspect historical sources & limits')}</a>`:comparison()}</section><section id="unknowns"><h2>${t('无法证实的部分','What remains unproven')}</h2><p>${t('本地同口径审批概率、完整房贷利率及房价／租金／就业的联动未齐。发布日缺失、许可待核和网络错误分别保留。没有“全球危机评分”。','Aligned local approval probabilities, complete mortgage rates and housing/rent/jobs relationships are incomplete. Missing release dates, licence gaps and network errors stay distinct. No global crisis score is produced.')}</p></section><section id="sources"><h2>${t('来源与继续提问','Sources & continuation')}</h2>${q.source_ids.map(source).join('')}<button data-handoff>${t('预览公共 Ask 交接范围','Preview public Ask handoff scope')}</button><div data-envelope></div><details ${consent?'open':''}><summary>${t('世界与我：可选自述','The world & me: optional note')}</summary><label><input type="checkbox" data-consent ${consent?'checked':''}>${t('我同意只在本页临时整理，不发送','I consent to temporary notes on this page, without sending')}</label>${consent?`<textarea data-private aria-label="${t('可选自述','Optional personal note')}">${esc(note)}</textarea><button data-clear>${t('清除','Clear')}</button>`:''}</details></section></article></div></main>`;}
function render(){document.documentElement.lang=state.lang;app.innerHTML=`<a href="#main" class="skip">${t('跳到正文','Skip to content')}</a><header class="top"><a href="?" data-home>PHI OS · World</a><div><button data-lang="zh-Hans">中文</button><button data-lang="en">EN</button></div></header><div class="wrap"><p class="eyebrow">${t('Gate 2C · 离线审阅；不执行模型、账户或生产写入','Gate 2C · Offline review; no model, account or production writes')}</p></div>${state.id||state.q?answer():home()}<footer class="wrap"><a href="../WORLD-R3-HUMAN-REVIEW.html">${t('返回同一人审入口','Return to the same Human Review')}</a></footer>`;bind();}function bind(){app.querySelectorAll('[data-home]').forEach(a=>a.onclick=e=>{e.preventDefault();go({id:'',q:''})});app.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>go({lang:b.dataset.lang}));app.querySelectorAll('[data-question]').forEach(a=>a.onclick=e=>{e.preventDefault();const q=D.questions.find(x=>x.id===a.dataset.question);go({id:q.id,q:local(q.title),country:q.country==='GLOBAL'?state.country:q.country,period:q.period})});app.querySelector('[data-search]')?.addEventListener('submit',e=>{e.preventDefault();const q=new FormData(e.target).get('q').trim();if(!q)return;const norm=s=>s.normalize('NFKC').toLowerCase().replace(/[?？。，,.!！\s]/g,'');const found=D.questions.find(x=>Object.values(x.title).some(s=>norm(s)===norm(q)));go({q,id:found?.id||'unknown'});});app.querySelector('[data-country]')?.addEventListener('change',e=>go({country:e.target.value}));app.querySelector('[data-period]')?.addEventListener('change',e=>go({period:e.target.value}));app.querySelectorAll('[data-scale]').forEach(b=>{b.onclick=()=>go({scale:b.dataset.scale});b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const ids=['now','history','compare'],i=ids.indexOf(state.scale);go({scale:ids[(i+(e.key==='ArrowRight'?1:2))%3]});app.querySelector('[data-scale="'+state.scale+'"]').focus();}});app.querySelector('[data-handoff]')?.addEventListener('click',()=>{const q=D.questions.find(x=>x.id===state.id),payload={originalQuestion:state.q||local(q.title),lang:state.lang,country:state.country,period:state.period,topic:'housing_credit',readingScale:state.scale,sourceContext:q.source_ids,execution:'PREVIEW_ONLY_NOT_SUBMITTED'};app.querySelector('[data-envelope]').innerHTML=`<pre class="public-envelope">${esc(JSON.stringify(payload,null,2))}</pre><p>${t('仅交接设计预览；真实产品完整接线仍待 Gate 3。','Handoff design preview only; full product wiring awaits Gate 3.')}</p>`;});app.querySelector('[data-consent]')?.addEventListener('change',e=>{consent=e.target.checked;note='';render()});app.querySelector('[data-private]')?.addEventListener('input',e=>note=e.target.value);app.querySelector('[data-clear]')?.addEventListener('click',()=>{consent=false;note='';render()});}window.onpopstate=()=>{consent=false;note='';read();render()};read();render();window.__gmch={state:()=>({...state}),privateState:()=>({consent,hasNote:!!note})};

function cpiChart(){if(state.country!=='MYS'||state.period!=='2024')return '';const rows=D.observations.filter(o=>o.metric_id==='cpi'&&o.country==='MYS'&&o.observation_period.startsWith('2024')).sort((a,b)=>a.observation_period.localeCompare(b.observation_period));const min=130,max=135,points=rows.map((o,i)=>(55+i*43)+','+(210-(o.value-min)/(max-min)*150)).join(' ');return '<figure class="map-outline"><figcaption>'+t('马来西亚2024年：月度总体CPI，2010=100','Malaysia2024: monthly overall CPI,2010=100')+'</figcaption><svg viewBox="0 0 580 260" role="img" aria-label="'+t('十二个月CPI观察，指数不是通胀百分比','Twelve monthly CPI observations; index not inflation percentage')+'"><line x1="55" y1="210" x2="540" y2="210" stroke="#6b817c"/><line x1="55" y1="60" x2="55" y2="210" stroke="#6b817c"/><text x="8" y="65">135</text><text x="8" y="210">130</text><text x="48" y="240">01</text><text x="515" y="240">12</text><polyline fill="none" stroke="#0b6863" stroke-width="3" points="'+points+'"/></svg><p class="minor">'+t('来源：DOSM；CC BY4.0。2026-10-20取样的历史修订版，各观察首发日未保留。仅说明价格篮子，不证明贷款审批严格程度。','Source:DOSM;CC BY4.0. Historical revised vintage sampled2026-10-20; initial release dates not retained. Basket prices do not establish mortgage approval strictness.')+'</p></figure>';}
function publisher(v){return ({Federal_Reserve_Board:t('美国联邦储备委员会','Federal Reserve Board'),Federal_Reserve_Bank_New_York:t('纽约联邦储备银行','Federal Reserve Bank of New York'),FFIEC_CFPB:t('美国金融机构检查委员会／消费者金融保护局','FFIEC / CFPB'),NBS_China:t('中国国家统计局','National Bureau of Statistics of China'),Bank_of_England:t('英格兰银行','Bank of England'),JPPH_NAPIC:t('马来西亚国家房地产资讯中心','NAPIC'),BNM:t('马来西亚国家银行','Bank Negara Malaysia'),JHF:t('日本住宅金融支援机构','Japan Housing Finance Agency'),BIS:t('国际清算银行','BIS'),ECB:t('欧洲中央银行','ECB'),DOSM:t('马来西亚统计局','DOSM'),CFPB:t('美国消费者金融保护局','CFPB')})[v]||v;}
function loanChart(){if(state.country!=='MYS'||state.period!=='2024')return '';const sets=[['application_amount','#0c605d',t('申请金额','Applied')],['approval_amount','#a77b2e',t('批准金额','Approved')],['disbursement_amount','#456393',t('放款金额','Disbursed')]].map(([id,color,label])=>({color,label,rows:D.observations.filter(o=>o.metric_id===id&&o.country==='MYS'&&o.observation_period.startsWith('2024')).sort((a,b)=>a.observation_period.localeCompare(b.observation_period))}));const max=Math.ceil(Math.max(...sets.flatMap(s=>s.rows.map(o=>o.value)))/1e10)*10;return '<figure class="map-outline"><figcaption>'+t('马来西亚住宅用途贷款：月度金额（十亿令吉）','Malaysia residential-purpose loans: monthly amounts (MYR billion)')+'</figcaption><svg viewBox="0 0 580 260" role="img" aria-label="'+t('申请、批准及放款金额；不是成功率','Applied, approved and disbursed amounts; not success probability')+'"><line x1="55" y1="210" x2="540" y2="210" stroke="#6b817c"/><text x="8" y="60">'+max+'</text><text x="12" y="210">0</text><text x="50" y="240">2024-01</text><text x="470" y="240">2024-12</text>'+sets.map(s=>'<polyline fill="none" stroke="'+s.color+'" stroke-width="3" points="'+s.rows.map((o,i)=>(55+i*43)+','+(210-o.value/1e9/max*150)).join(' ')+'"/>').join('')+'</svg><p>'+sets.map(s=>'<span style="color:'+s.color+'">'+s.label+'</span>').join(' · ')+'</p><p class="minor">'+t('来源：马来西亚国家银行／官方CCRIS汇总。原值令吉除以十亿；同月不是同一申请群组，不计算获批概率。首发日期未保留，2026-10-20取得。','Source: Bank Negara Malaysia / official CCRIS aggregates. Original MYR divided by1billion; same-month flows are not a matched application cohort. No approval probability is calculated. Initial release dates not retained; retrieved2026-10-20.')+'</p></figure>';}